def notional_cents(price_cents, quantity_shares):
    for name, value in [("price_cents", price_cents), ("quantity_shares", quantity_shares)]:
        if type(value) is not int or value < 0:
            raise ValueError(f"{name} must be a nonnegative integer")
    return price_cents * quantity_shares

print(notional_cents(207, 3))
for bad in [True, -1, "3", 3.0]:
    try:
        notional_cents(207, bad)
    except ValueError:
        print("rejected")

def total_quantities(values):
    if type(values) is not list:
        raise ValueError("expected a list")
    if any(type(v) is not int or v < 0 for v in values):
        raise ValueError("invalid quantity")
    return sum(values)

print(total_quantities([2, 0, 4]))
try:
    print(total_quantities([2, -1, 4]))
except ValueError:
    print("batch rejected")
